import{_ as r,l as d,o as a,c as o,v as l,p as s,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"idle 线程","description":"","frontmatter":{"title":"idle 线程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/idle-thread.md","filePath":"cs/idle-thread.md","lastUpdated":1789023840000}'),h={name:"cs/idle-thread.md"};function _(m,e,u,E,A,f){const i=d("Mermaid");return a(),o("div",null,[e[1]||(e[1]=l('<h1 id="idle-线程" tabindex="-1">idle 线程 <a class="header-anchor" href="#idle-线程" aria-label="Permalink to &quot;idle 线程&quot;">​</a></h1><div class="epigraph"><p>每颗 CPU 始终要有一条可运行的任务：没有用户工作时，就跑 idle——停机等待中断，而不是在空队列上空转调度器。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 整理</footer></div><p><a href="/cs/fpu-lazy">上一课</a>降低了切换时的寄存器搬运。调度器仍要回答：就绪集合为空时把程序计数器指到哪。若「没有任务」就让 CPU 执行垃圾，机器会飞。<a href="/cs/percpu">per-CPU 数据</a> 已有核本地状态。缺口是每 CPU 一条 <strong>idle 线程</strong>：永远可运行、优先级最低，体内停机或低功耗等待，被中断叫醒后再进入调度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时钟与设备 IRQ 必须有一个执行上下文来跑上半部；若 CPU 真的「什么都没有」，连中断返回后要恢复的 PCB 都不存在。idle 提供这个底：它是内核线程，无用户地址空间，调度类里排在所有真正工作之后。缺口不是 FPU 策略，而是<strong>空转的合法形态</strong>。</p><p><span class="marginnote">idle 里调用 <code>wait_for_interrupt</code> 一类指令，打开中断并停核。唤醒后先跑 ISR，再看是否有新就绪任务；没有则再次停。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动时为每个 CPU 创建 idle <code>task_struct</code>，永不退出。主调度循环：选最高优先级就绪任务；若无，选 idle。idle 不累计用户时间。负载统计常把 idle 时间单独记账，以免把「核在睡觉」当成「核在跑公平份额」。</p>',8)),(a(),s(p,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%E7%A9%BA%3F%22%5D%20--%3E%20I%5B%22%E8%B7%91%20idle%3A%20%E5%81%9C%E6%9C%BA%E7%AD%89%E4%B8%AD%E6%96%AD%22%5D%0A%20%20Q%20--%3E%20R%5B%22%E8%B7%91%E6%99%AE%E9%80%9A%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20I%20--%3E%20IRQ%5B%22%E4%B8%AD%E6%96%AD%E5%94%A4%E9%86%92%22%5D%0A%20%20IRQ%20--%3E%20Q%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<p>禁止在 idle 里做重活；否则等于偷了一个永远可运行的低优先级工人，延迟难以解释。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>idle 让「CPU 利用率」有定义：非 idle 时间 / 墙钟。与<a href="/cs/interrupt-bottom-half">中断下半部</a>会合：设备完成把线程唤醒，idle 被抢占。与内核抢占：idle 自己可被立即切走，因为它不持用户锁。功耗：深 C-state 进 idle 再进，退出延迟是实时课的 WCET 来源之一，本课只承认停机有代价。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 cpuidle 治理器的全部策略写成电源管理课。也不把「空循环 busy idle」当现代默认。tickless 内核如何关掉空闲核上的时钟中断，点到即可。</p><p>后课默认：CPU 上永远有当前任务，可能是 idle。有多条真工作时如何比较好坏，下一课先定义<a href="/cs/scheduling-metrics">调度指标</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每 CPU 一条 idle：队列空则停机等中断。</li><li>利用率相对 idle 来定义；idle 不做重活。</li><li>尺子（周转、响应、公平）是下一课。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const C=r(h,[["render",_]]);export{B as __pageData,C as default};
